import { readFile } from "node:fs/promises";

import { eq } from "drizzle-orm";
import { z } from "zod";

import * as tables from "../db/schema.ts";
import { collectionSchema } from "./model.ts";
import { importCollection, readRanking } from "./store.ts";

const [command, argument, ...extra] = process.argv.slice(2);

try {
  if (extra.length > 0) {
    throw new Error("Too many arguments");
  }

  switch (command) {
    case "schema": {
      console.log(JSON.stringify(z.toJSONSchema(collectionSchema, { io: "input" }), null, 2));
      break;
    }
    case "validate":
    case "import": {
      if (!argument) {
        throw new Error(`Usage: vp run data:${command} <collection.json>`);
      }
      const collection = collectionSchema.parse(JSON.parse(await readFile(argument, "utf8")));
      if (command === "validate") {
        console.log(`Valid collection ${collection.id}: ${collection.restaurants.length} restaurants`);
        break;
      }

      const { db } = await import("../db/index.ts");
      try {
        console.log(JSON.stringify(importCollection(db, collection)));
      } finally {
        db.$client.close();
      }
      break;
    }
    case "report":
    case "inspect": {
      if (command === "inspect" && !argument) {
        throw new Error("Usage: vp run data:inspect <collection-id>");
      }
      const { db } = await import("../db/index.ts");
      try {
        if (command === "report") {
          console.log(JSON.stringify(readRanking(db), null, 2));
          break;
        }

        // The command guard above establishes the ID; keep the narrowed value explicit.
        if (!argument) {
          throw new Error("A collection ID is required");
        }
        const collection = db.select().from(tables.collections)
          .where(eq(tables.collections.id, argument)).get();
        if (!collection) {
          throw new Error(`Unknown collection: ${argument}`);
        }
        console.log(JSON.stringify({
          collection,
          restaurants: db.select().from(tables.restaurantSnapshots)
            .where(eq(tables.restaurantSnapshots.collectionId, argument)).all(),
          observations: db.select().from(tables.dinnerObservations)
            .where(eq(tables.dinnerObservations.collectionId, argument)).all(),
          scores: db.select().from(tables.scarcityScores)
            .where(eq(tables.scarcityScores.collectionId, argument)).all(),
        }, null, 2));
      } finally {
        db.$client.close();
      }
      break;
    }
    default:
      throw new Error("Expected schema, validate <file>, import <file>, report, or inspect <collection-id>");
  }
} catch (error) {
  console.error(error instanceof Error ? error.message : "Data command failed");
  process.exitCode = 1;
}

