import { readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';

const require = createRequire(`${process.cwd()}/package.json`);
const { z } = require('zod');
const directory = '/tmp/resy-network-proof.9Kv7L5';
const endpoint = 'https://api.resy.com/3/venuesearch/search';

const harSchema = z.object({
  log: z.object({
    entries: z.array(z.object({
      request: z.object({
        method: z.string(),
        url: z.string(),
        headers: z.array(z.object({ name: z.string(), value: z.string() })),
        postData: z.object({ text: z.string() }).optional(),
      }),
      response: z.object({
        status: z.number(),
        content: z.object({ text: z.string().optional() }),
      }),
    })),
  }),
});

// Validate only the fields needed for this replay comparison, not an API client.
const responseSchema = z.object({
  meta: z.object({
    page: z.number().int(),
    per_page: z.number().int(),
    total: z.number().int(),
    total_pages: z.number().int(),
  }),
  search: z.object({
    hits: z.array(z.object({
      id: z.object({ resy: z.number().int() }),
      name: z.string(),
      locality: z.string(),
      is_tock_inventory: z.boolean(),
      availability: z.object({
        slots: z.array(z.object({
          date: z.object({ start: z.string(), end: z.string() }),
          is_global_dining_access: z.boolean(),
          exclusive: z.object({ id: z.number(), is_eligible: z.boolean() }),
        })),
      }),
    })),
  }),
});

const har = harSchema.parse(JSON.parse(await readFile(`${directory}/search.har`, 'utf8')));
const entry = har.log.entries.find(({ request, response }) =>
  request.method === 'POST' && request.url === endpoint && response.status === 200 &&
  request.postData && JSON.parse(request.postData.text).availability === true,
);
if (!entry?.request.postData || !entry.response.content.text) {
  throw new Error('No successful availability search with a captured response body.');
}
const original = responseSchema.parse(JSON.parse(entry.response.content.text));
const headers = new Headers();
for (const { name, value } of entry.request.headers) headers.set(name, value);

const response = await fetch(endpoint, {
  method: 'POST',
  headers,
  body: entry.request.postData.text,
  redirect: 'error',
  signal: AbortSignal.timeout(20_000),
});
const body = await response.text();
await writeFile(`${directory}/search-replay-response.json`, body, { mode: 0o600 });
console.log(JSON.stringify({ status: response.status, observedAt: new Date().toISOString() }));
if (!response.ok) process.exit(1);

const replay = responseSchema.parse(JSON.parse(body));
console.log(JSON.stringify({
  pagination: replay.meta,
  matchesCapturedFields: JSON.stringify(replay) === JSON.stringify(original),
  venues: replay.search.hits.map((hit) => ({
    id: hit.id.resy,
    name: hit.name,
    locality: hit.locality,
    isTockInventory: hit.is_tock_inventory,
    slots: hit.availability.slots,
  })),
}, null, 2));

