  --secondary: #f2f2f2;
  --secondary-foreground: #0a0a0a;
  --muted: #f4f4f4;
  --muted-foreground: #5f5f5f;
  --faint: #737373;
  --accent: #f2f2f2;
  --accent-foreground: #0a0a0a;
  --destructive: #d93036;
  --border: #e6e6e6;
  --input: #e6e6e6;
