import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";

import { restaurantCaptureSchema } from "../scarcity/model.ts";

export const rankingSearchSchema = z.object({
  venue: restaurantCaptureSchema.shape.resyUrl.optional().catch(undefined),
});

export const getRankingData = createServerFn({ method: "GET" })
  .inputValidator(rankingSearchSchema)
  .handler(async ({ data }) => {
    const { db } = await import("../db/index.ts");
    const { readRankingPage } = await import("./ranking.server.ts");
    return readRankingPage(db, data.venue);
  });

export type RankingData = Awaited<ReturnType<typeof getRankingData>>;
export type RestaurantRow = RankingData["restaurants"][number];
export type RestaurantDetailData = NonNullable<RankingData["detail"]>;

import { TIME_ZONE } from "../scarcity/model.ts";
import type { Observation } from "../scarcity/model.ts";

export type DayStatus = Observation["status"] | "missing";

export const statusLabel: Record<DayStatus, string> = {
  available: "Available",
  unavailable: "No opening",
  non_service: "No dinner service",
  unreleased: "Not released",
  unknown: "Unknown",
  collection_error: "Request failed",
  missing: "Not checked",
};

const diningDateFormat = new Intl.DateTimeFormat("en-US", {
  timeZone: "UTC", month: "short", day: "numeric",
});
const snapshotFormat = new Intl.DateTimeFormat("en-US", {
  timeZone: "UTC", month: "long", day: "numeric", year: "numeric",
});
const instantFormat = new Intl.DateTimeFormat("en-US", {
  timeZone: TIME_ZONE, month: "short", day: "numeric", hour: "numeric",
  minute: "2-digit", timeZoneName: "short",
});
const weekdayFormat = new Intl.DateTimeFormat("en-US", { timeZone: "UTC", weekday: "short" });

export function formatDay(day: string) {
  return diningDateFormat.format(new Date(`${day}T12:00:00Z`));
}

export function formatSnapshot(day: string) {
  return snapshotFormat.format(new Date(`${day}T12:00:00Z`));
}

export function formatWeekday(day: string) {
  return weekdayFormat.format(new Date(`${day}T12:00:00Z`));
}

export function formatInstant(instant: string) {
  return instantFormat.format(new Date(instant));
}

export function formatScore(score: number) {
  return new Intl.NumberFormat("en-US", { maximumFractionDigits: 1 }).format(score);
}

import { Fragment, useState } from "react";
import { ArrowDown, ChevronRight, Search } from "lucide-react";

import { formatDay, formatScore, formatSnapshot, statusLabel } from "./format.ts";
import type { RankingData, RestaurantRow } from "./ranking.functions.ts";
import { RestaurantDetail } from "./restaurant-detail.tsx";

type Group = "ranked" | "review" | "excluded";
const groups: { id: Group; label: string }[] = [
  { id: "ranked", label: "Ranked" },
  { id: "review", label: "Needs review" },
  { id: "excluded", label: "Excluded" },
];

function groupOf(restaurant: Pick<RestaurantRow, "eligibility" | "score">): Group {
  if (restaurant.eligibility === "excluded") return "excluded";
  return restaurant.score === null ? "review" : "ranked";
}

function searchText(value: string) {
  return value.normalize("NFD").replace(/\p{Diacritic}/gu, "").toLowerCase();
}

export function RankingPage({ data, expandedUrl, onToggle }: {
  data: RankingData;
  expandedUrl: string | undefined;
  onToggle: (url: string) => void;
}) {
  const [group, setGroup] = useState<Group>(() => data.detail ? groupOf(data.detail.restaurant) : "ranked");
  const [query, setQuery] = useState("");
  const counts: Record<Group, number> = { ranked: 0, review: 0, excluded: 0 };
  let snapshotDate: string | null = null;
  for (const row of data.restaurants) {
    counts[groupOf(row)]++;
    if (!snapshotDate || row.anchorDate > snapshotDate) snapshotDate = row.anchorDate;
  }
  const needle = searchText(query.trim());
  const rows = data.restaurants.filter((row) =>
    groupOf(row) === group && searchText(`${row.name} ${row.address ?? ""}`).includes(needle),
  );

  return (
    <main className="ranking-page">
      <header className="ranking-header">
        <p className="eyebrow">RESY / SAN FRANCISCO</p>
        <h1>Hard-to-book restaurants</h1>
        <p className="scope">Party of two <span aria-hidden="true">·</span> Dinner, 6–9 p.m. <span aria-hidden="true">·</span> San Francisco time</p>
        <div className="snapshot-line">
          {snapshotDate ? <span>Snapshot: {formatSnapshot(snapshotDate)}</span> : <span>No data collected yet</span>}
          <span className="coverage-note">Partial coverage, not a citywide ranking</span>
        </div>
        <details className="method">
          <summary>How the score works</summary>
          <div>
            <p><strong>Score = 100 × dinner dates with no opening ÷ assessed dinner dates.</strong> Higher means harder access. We compare the same next seven calendar days, starting the day after each snapshot. Each date counts once; the number of slots does not affect the score.</p>
            <p>Confirmed non-service dates leave the denominator. A score needs every date accounted for and at least one dinner-service date. Unknown, unreleased, missing or failed dates prevent scoring. Closed venues, events, other-platform-only listings and venues outside SF do not earn scarcity points.</p>
            <p>The scale is fixed at 0–100, not a percentile. Later weeks provide context, not extra weight. This measures observed public Resy access, not occupancy, booking volume, prestige or a forecast. Open a restaurant to inspect its dates and sources.</p>
          </div>
        </details>
      </header>

      <section aria-label="Restaurant ranking">
        <div className="table-tools">
          <div className="status-filters" role="group" aria-label="Restaurant status">
            {groups.map((item) => (
              <button key={item.id} type="button" aria-pressed={group === item.id} onClick={() => setGroup(item.id)}>
                {item.label} <span>{counts[item.id]}</span>
              </button>
            ))}
          </div>
          <label className="restaurant-search">
            <Search size={16} aria-hidden="true" />
            <span className="sr-only">Search restaurants</span>
            <input type="search" placeholder="Search restaurants" value={query} onChange={(event) => setQuery(event.target.value)} />
          </label>
        </div>
        {group === "review" ? <p className="group-note">Incomplete observations or unresolved Resy eligibility. These restaurants are not ranked; a missing score does not mean easy access.</p> : null}
        {group === "excluded" ? <p className="group-note">Outside this comparison. Exclusion reasons are based on geography, service or booking evidence, not on empty calendars.</p> : null}
        <div className="ranking-table-wrap">
          <table className="ranking-table">
            <caption className="sr-only">{groups.find((item) => item.id === group)?.label} restaurants. Scored restaurants are ordered by scarcity, highest first. Equal scores are ties.</caption>
            <thead>
              <tr>
                <th scope="col">Restaurant</th>
                <th scope="col" aria-sort={group === "ranked" ? "descending" : undefined}>Scarcity {group === "ranked" ? <ArrowDown size={12} aria-hidden="true" /> : null}</th>
                <th scope="col">No opening</th>
                <th scope="col" className="week-column">Next 7 nights</th>
                <th scope="col" className="opening-column">First opening seen</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((restaurant) => {
                const expanded = expandedUrl === restaurant.resyUrl;
                return (
                  <Fragment key={restaurant.resyUrl}>
                    <tr className={expanded ? "expanded-row" : undefined}>
                      <td>
                        <button className="restaurant-name" type="button" aria-expanded={expanded} onClick={() => onToggle(restaurant.resyUrl)}>
                          <ChevronRight size={15} aria-hidden="true" className={expanded ? "chevron-open" : undefined} />
                          <span>{restaurant.name}</span>
                        </button>
                        {group !== "ranked" ? <p className="row-reason">{restaurant.eligibility === "eligible" ? restaurant.scoreReason : restaurant.eligibilityReason}</p> : null}
                      </td>
                      <td className="score-cell">
                        {restaurant.score === null ? <span className="unscored" aria-label="Not scored">—</span> : <>
                          <span className="score-number">{formatScore(restaurant.score)}</span>
                          <div className="score-track" aria-hidden="true"><span style={{ width: `${restaurant.score}%` }} /></div>
                        </>}
                      </td>
                      <td className="fraction-cell">
                        {restaurant.score !== null ? <>
                          <span title={`${restaurant.unavailable} of ${restaurant.assessed} assessed dinner dates had no qualifying opening`}>{restaurant.unavailable}<span className="muted"> / {restaurant.assessed}</span></span>
                          {restaurant.nonService > 0 ? <small>{restaurant.nonService} non-service</small> : null}
                        </> : <span className="muted">—</span>}
                      </td>
                      <td className="week-column">
                        <div className="week-strip" aria-label="Headline week observations">
                          {restaurant.week.map((day) => <span key={day.diningDate} className="day-mark" data-status={day.status} title={`${formatDay(day.diningDate)}: ${statusLabel[day.status]}`}><span className="sr-only">{formatDay(day.diningDate)}: {statusLabel[day.status]}</span></span>)}
                        </div>
                      </td>
                      <td className="opening-column first-opening">{restaurant.earliestAvailableDate ? formatDay(restaurant.earliestAvailableDate) : <span className="muted">Not observed</span>}</td>
                    </tr>
                    {expanded && data.detail?.restaurant.resyUrl === restaurant.resyUrl ? <tr className="detail-row"><td colSpan={5}><RestaurantDetail key={restaurant.resyUrl} detail={data.detail} /></td></tr> : null}
                  </Fragment>
                );
              })}
              {rows.length === 0 ? <tr><td colSpan={5} className="empty-table">{query ? "No matching restaurants in this group. Try another name or status." : "No restaurants in this group yet."}</td></tr> : null}
            </tbody>
          </table>
        </div>
        <footer className="table-footer">
          <span>{rows.length} restaurant{rows.length === 1 ? "" : "s"}{query ? " matching" : " shown"}</span>
          <span>0 = easy access observed. 100 = no qualifying opening on assessed dates.</span>
        </footer>
      </section>
    </main>
  );
}

import { useState } from "react";
import { ArrowUpRight } from "lucide-react";

import { addDays } from "../scarcity/model.ts";
import type { Evidence } from "../scarcity/model.ts";
import { formatDay, formatInstant, formatScore, formatWeekday, statusLabel } from "./format.ts";
import type { DayStatus } from "./format.ts";
import type { RestaurantDetailData } from "./ranking.functions.ts";

function SourceNotes({ evidence }: { evidence: Evidence[] }) {
  const unique = new Map(evidence.map((item) => [`${item.url}\n${item.quote}`, item]));
  return (
    <ul className="source-notes">
      {[...unique].map(([key, item]) => {
        const url = new URL(item.url);
        return <li key={key}>
          <blockquote>{item.quote}</blockquote>
          <p>{url.hostname === "api.resy.com" ? <span>Captured Resy API response</span> : <a href={item.url} target="_blank" rel="noreferrer">{url.hostname} <ArrowUpRight size={12} aria-hidden="true" /></a>} <span>· {formatInstant(item.observedAt)}</span></p>
        </li>;
      })}
    </ul>
  );
}

export function RestaurantDetail({ detail }: { detail: RestaurantDetailData }) {
  const { restaurant, observations } = detail;
  const [selectedDate, setSelectedDate] = useState(addDays(restaurant.anchorDate, 1));
  const byDate = new Map(observations.map((observation) => [observation.diningDate, observation]));
  const days = Array.from({ length: 28 }, (_, index) => {
    const diningDate = addDays(restaurant.anchorDate, index + 1);
    const status: DayStatus = byDate.get(diningDate)?.status ?? "missing";
    return { diningDate, status };
  });
  const selected = byDate.get(selectedDate);
  const selectedStatus = selected?.status ?? "missing";
  const sourceEvidence = selected ? [...selected.evidence] : [];
  if (selected?.status === "unavailable") sourceEvidence.push(selected.releaseEvidence, selected.serviceEvidence);
  const showCalendar = restaurant.eligibility !== "excluded" && observations.length > 0;

  return (
    <article className="restaurant-detail" aria-label={`${restaurant.name} evidence`}>
      <header className="detail-heading">
        <p>{restaurant.address ?? "Street address not verified"}</p>
        <a href={restaurant.resyUrl} target="_blank" rel="noreferrer">Open on Resy <ArrowUpRight size={14} aria-hidden="true" /></a>
      </header>
      {restaurant.score === null ? <p className="review-reason">{restaurant.eligibility === "eligible" ? restaurant.scoreReason : restaurant.eligibilityReason}</p> : null}
      {showCalendar ? <div className="detail-grid">
        <section aria-label="Dinner availability by date">
          <div className="band-scores">
            {detail.bands.map((band) => <div key={band.startDay}>
              <span>Days {band.startDay}–{band.endDay}</span>
              <strong>{band.score === null ? "—" : formatScore(band.score)}</strong>
              <small>{band.score === null ? "Incomplete" : `${band.unavailable}/${band.assessed} no opening`}</small>
            </div>)}
          </div>
          <div className="dinner-calendar" aria-label="28-day dinner calendar">
            {days.slice(0, 7).map((day) => <span className="weekday-label" key={day.diningDate}>{formatWeekday(day.diningDate)}</span>)}
            {days.map((day) => <button key={day.diningDate} type="button" data-status={day.status} aria-pressed={day.diningDate === selectedDate} aria-label={`${formatDay(day.diningDate)}: ${statusLabel[day.status]}`} onClick={() => setSelectedDate(day.diningDate)}>
              {Number(day.diningDate.slice(-2))}
            </button>)}
          </div>
          <ul className="calendar-legend">
            <li><span className="day-mark" data-status="available" />Available</li>
            <li><span className="day-mark" data-status="unavailable" />No opening</li>
            <li><span className="day-mark" data-status="non_service" />No service</li>
            <li><span className="day-mark" data-status="unknown" />Unknown / unchecked</li>
          </ul>
        </section>
        <section className="date-evidence" aria-live="polite">
          <h2>{formatDay(selectedDate)} <span>{statusLabel[selectedStatus]}</span></h2>
          {selected?.status === "available" ? <p>Observed dinner starts: {[...new Set(selected.slots.map((slot) => slot.time))].join(", ")}. Local time, party of two.</p> : null}
          {selectedStatus === "missing" ? <p>This date was not captured for this restaurant. It is not counted as unavailable.</p> : null}
          {selectedStatus === "unknown" ? <p>The evidence does not establish availability or a released, unavailable dinner date. This date prevents a score for its week.</p> : null}
          {selectedStatus === "unavailable" ? <p>No qualifying public dinner opening was observed. Release and regular service are supported by the sources below; this does not prove full occupancy.</p> : null}
          {selected ? <p className="observed-at">Observed {formatInstant(selected.observedAt)}</p> : null}
          {sourceEvidence.length > 0 ? <details className="evidence-disclosure"><summary>Evidence for this date</summary><SourceNotes evidence={sourceEvidence} /></details> : null}
        </section>
      </div> : null}
      {restaurant.bookingPolicy ? <p className="booking-policy"><strong>Booking policy.</strong> {restaurant.bookingPolicy}</p> : null}
      <details className="evidence-disclosure"><summary>Restaurant sources &amp; collection notes</summary>
        <SourceNotes evidence={detail.evidence} />
        <p className="collection-selection">{detail.collection.selection}</p>
        <ul className="collection-limitations">{detail.collection.limitations.map((limitation) => <li key={limitation}>{limitation}</li>)}</ul>
      </details>
    </article>
  );
}

import { createFileRoute, useRouter } from "@tanstack/react-router";

import { RankingPage } from "../ranking/ranking-page.tsx";
import { getRankingData, rankingSearchSchema } from "../ranking/ranking.functions.ts";

export const Route = createFileRoute("/")({
  validateSearch: rankingSearchSchema,
  loaderDeps: ({ search }) => ({ venue: search.venue }),
  loader: ({ deps }) => getRankingData({ data: deps }),
  component: RankingRoute,
  errorComponent: RankingError,
  pendingComponent: () => <main className="ranking-page"><p>Loading restaurant observations…</p></main>,
});

function RankingRoute() {
  const data = Route.useLoaderData();
  const { venue } = Route.useSearch();
  const navigate = Route.useNavigate();

  function toggle(url: string) {
    void navigate({
      search: { venue: url === venue ? undefined : url },
      replace: true,
      resetScroll: false,
    });
  }

  return <RankingPage data={data} expandedUrl={venue} onToggle={toggle} />;
}

function RankingError() {
  const router = useRouter();
  return <main className="ranking-page">
    <h1>Restaurant data could not load</h1>
    <p>Check that the local database is available and its migrations have been applied.</p>
    <button type="button" className="retry-button" onClick={() => void router.invalidate()}>Try again</button>
  </main>;
}

