import { readFile, readdir, writeFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { collectionSchema, addDays, type Evidence, type RestaurantCapture } from '/home/drsh4dow/Projects/data-engineering-exercise/src/scarcity/model.ts';
import { searchResponseSchema, type NativeSearchHit } from '/home/drsh4dow/Projects/data-engineering-exercise/src/scarcity/resy.ts';

const base = collectionSchema.parse(JSON.parse(await readFile('data/collections/2026-09-30-search-snapshot.json', 'utf8')));
const reviewed: RestaurantCapture[] = [];
function venue(name: string) {
  const value = base.restaurants.find((restaurant) => restaurant.name === name);
  if (!value) throw new Error(`Missing review target ${name}`);
  reviewed.push(value);
  return value;
}
function evidence(url: string, time: string, quote: string): Evidence {
  return { url, observedAt: `2026-09-30T${time}Z`, quote };
}
const raw = new Map<string, NativeSearchHit>();
const files = await readdir('/tmp/resy-sf-search-20260930');
files.sort();
for (const file of files.filter((name) => name.startsWith('search-') && name.endsWith('.json'))) {
  const capture = JSON.parse(await readFile(`/tmp/resy-sf-search-20260930/${file}`, 'utf8'));
  const response = searchResponseSchema.parse(capture.response);
  for (const hit of response.search.hits) {
    if (hit.is_tock_inventory || !['Izakaya Rintaro', 'Flour + Water'].includes(hit.name)) continue;
    const key = `${hit.name}:${capture.day}`;
    if (!raw.has(key)) raw.set(key, hit);
  }
}
function reviewNoOpenings(restaurant: RestaurantCapture, release: Evidence, service: Evidence) {
  if (!restaurant.observations.some((observation) => observation.status === 'available')) {
    throw new Error('This review requires observed regular public dinner inventory, not only a surviving listing.');
  }
  restaurant.evidence.push(release, service);
  restaurant.observations = restaurant.observations.map((observation) => {
    if (observation.status !== 'unknown') return observation;
    const hit = raw.get(`${restaurant.name}:${observation.diningDate}`);
    if (!hit || hit.availability.status !== null || Object.keys(hit.availability.gating_errors).length) return observation;
    const ambiguous = hit.availability.slots.some((slot) => {
      if (!slot.date.start.startsWith(`${observation.diningDate} `)) return true;
      const time = slot.date.start.slice(11);
      if (time < '18:00:00' || time > '21:00:00' || slot.is_global_dining_access || slot.exclusive.id !== 0 || !slot.exclusive.is_eligible) return false;
      const template = hit.availability.templates[String(slot.template.id)];
      return !template || template.is_event == null || template.is_pickup == null;
    });
    if (ambiguous) return observation;
    return {
      ...observation,
      status: 'unavailable' as const,
      evidence: [...observation.evidence, {
        url: 'https://api.resy.com/3/venuesearch/search', observedAt: observation.observedAt,
        quote: 'Evidence review: this venue was returned by the successful all-day party-of-two search, without inventory/gating errors or a qualifying public regular dinner slot. Classify observed search unavailability using the independently verified release and service policies; do not infer occupancy or sold-out causation.',
      }],
      releaseEvidence: release, serviceEvidence: service,
    };
  });
}
function nonService(restaurant: RestaurantCapture, weekdays: number[], source: Evidence) {
  restaurant.evidence.push(source);
  for (let offset = 1; offset <= 28; offset++) {
    const day = addDays('2026-09-30', offset);
    if (!weekdays.includes(new Date(`${day}T12:00:00Z`).getUTCDay())) continue;
    const index = restaurant.observations.findIndex((observation) => observation.diningDate === day);
    if (index >= 0 && restaurant.observations[index].status === 'available') throw new Error(`Service-policy conflict: ${restaurant.name} ${day}`);
    const observation = { diningDate: day, observedAt: source.observedAt, status: 'non_service' as const, evidence: [source] };
    if (index >= 0) restaurant.observations[index] = observation;
    else restaurant.observations.push(observation);
  }
  restaurant.observations.sort((a, b) => a.diningDate.localeCompare(b.diningDate));
}

const rintaro = venue('Izakaya Rintaro');
rintaro.bookingPolicy = 'Public reservations for 1–8 guests release 28 days ahead at 10 a.m.; dinner daily, 5–10 p.m. Release timezone is interpreted as local SF time. Courtyard seating counts; walk-in capacity is not measured.';
reviewNoOpenings(rintaro,
  evidence('https://izakayarintaro.com/', '22:58:14', 'Reservations are bookable through Resy up to 28 days in advance starting at 10:00 a.m. Walk-in seating is very limited.'),
  evidence('https://izakayarintaro.com/', '22:58:14', 'Open 5:00 p.m. daily, last seating 10:00 p.m.'),
);
rintaro.evidence.push(evidence('https://resy.com/cities/san-francisco-ca/search?date=2026-10-03&seats=2&query=Rintaro', '23:11:09', 'Browser observation: Izakaya Rintaro was the sole venue returned for two guests on October 3. Its card showed Notify and no reservation time buttons, with no visible UI error. The 7 p.m. filter repeated this result at 23:11:16Z.'));

const flour = venue('Flour + Water');
flour.bookingPolicy = 'Resy reservations release 28 days ahead at midnight; dinner seven days a week, 5–9:30 p.m. Release timezone is interpreted as SF local time. Public tasting menus count; Global Dining Access-only inventory and reserved walk-in capacity do not.';
reviewNoOpenings(flour,
  evidence('https://www.flourandwater.com/faq/', '22:58:33', 'Reservations are exclusively available through Resy and will not be made over the phone or email. Reservations are released 28 days in advance at midnight. Please note that we do encourage walk-ins and save a portion of our dining room nightly for walk-in guests.'),
